(function(){const gaId = "G-SGQH7NCGFG";

        // gtag.js is the largest single source of main-thread blocking
        // and unused JS on first paint. We seed dataLayer + queue the
        // initial events synchronously (so no analytics events are
        // lost) and then defer the actual gtag.js download until the
        // page is interactive, first user interaction or 2s after
        // window.load, whichever comes first.
        window.dataLayer = window.dataLayer || [];
        function gtag() { dataLayer.push(arguments); }
        gtag("js", new Date());
        gtag("config", gaId);

        var loaded = false;
        function loadGtag() {
          if (loaded) return;
          loaded = true;
          var s = document.createElement("script");
          s.async = true;
          s.src = "https://www.googletagmanager.com/gtag/js?id=" + gaId;
          document.head.appendChild(s);
        }
        function scheduleIdle() { setTimeout(loadGtag, 2000); }
        if (document.readyState === "complete") {
          scheduleIdle();
        } else {
          window.addEventListener("load", scheduleIdle, { once: true });
        }
        ["pointerdown", "keydown", "touchstart", "scroll"].forEach(function (ev) {
          window.addEventListener(ev, loadGtag, { once: true, passive: true });
        });
      })();

(function(){const clarityId = "wqnkty3igj";

