        })(window, document, "clarity", "script", clarityId);
      })();

// FOUC guard, apply stored theme before first paint.
// Default is light; OS preference is ignored unless the user has
// explicitly opted into dark via the footer toggle.
(function () {
  try {
    const stored = localStorage.getItem("netlinks-theme");
    if (stored === "dark") document.documentElement.classList.add("dark");
  } catch {}
})();

